#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <pwd.h>
#include <systemd/sd-bus.h>

enum nss_status {
    NSS_STATUS_SUCCESS,
    NSS_STATUS_NOTFOUND,
    NSS_STATUS_UNAVAIL
};

enum nss_status get_user_account_info(const char *name, struct passwd *pwd, char *buffer, size_t buflen, int *errnop) {
    if (name == NULL || pwd == NULL || buffer == NULL || buflen == 0 || errnop == NULL) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    if (strncmp(name, "vu-", 3) != 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    const char *machine_start = name + 3;
    const char *uid_start = strchr(machine_start, '-');
    if (uid_start == NULL) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    // Calculate machine name
    size_t machine_len = uid_start - machine_start;
    if (machine_len == 0) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    char *machine_name = buffer;
    strncpy(machine_name, machine_start, machine_len);
    machine_name[machine_len] = '\0';

    // Validate that the rest of the string is numeric (UID)
    uid_start++;
    if (*uid_start == '\0') {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    char *endptr;
    uid_t uid = strtoul(uid_start, &endptr, 10);
    if (*endptr != '\0') {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus *bus = NULL;
    int r = sd_bus_default_system(&bus);
    if (r < 0) {
        *errnop = -r;
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus_message *m = NULL;
    r = sd_bus_call_method(
        bus,
        "org.freedesktop.systemd1",
        "/org/freedesktop/systemd1",
        "org.freedesktop.systemd1.Manager",
        "GetUserByUID",
        NULL,
        &m,
        "u",
        uid
    );

    if (r < 0) {
        *errnop = -r;
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    const char *username;
    r = sd_bus_message_read(m, "s", &username);
    if (r < 0) {
        *errnop = -r;
        sd_bus_message_unref(m);
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    if (username == NULL) {
        *errnop = 0;
        sd_bus_message_unref(m);
        sd_bus_unref(bus);
        return NSS_STATUS_NOTFOUND;
    }

    // Populate the password structure
    pwd->pw_name = username;
    pwd->pw_uid = uid;
    pwd->pw_gid = uid;
    pwd->pw_dir = "/home/unknown";
    pwd->pw_shell = "/bin/false";
    pwd->pw_gecos = "";

    sd_bus_message_unref(m);
    sd_bus_unref(bus);
    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}

