enum nss_status {
    NSS_STATUS_SUCCESS,
    NSS_STATUS_NOTFOUND,
    NSS_STATUS_UNAVAIL
};

enum nss_status get_user_info(const char* name, struct passwd* pwd, char* buffer, size_t buflen, int* errnop) {
    if (!name || !pwd || !buffer || buflen == 0 || !errnop) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    if (strncmp(name, "vu-", 3) != 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    const char* machine_start = name + 3;
    const char* uid_start = strchr(machine_start, '-');
    if (!uid_start) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    size_t machine_len = uid_start - machine_start;
    if (machine_len == 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    const char* uid_str = uid_start + 1;
    char* endptr;
    long uid = strtol(uid_str, &endptr, 10);
    if (uid_str == endptr || *endptr != '\0' || uid <= 0 || uid > UID_MAX) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    size_t name_len = 3 + machine_len + 1 + (size_t)(uid_str - machine_start - 1);
    if (name_len >= buflen) {
        *errnop = ENOSPC;
        return NSS_STATUS_UNAVAIL;
    }

    snprintf(buffer, buflen, "vu-%.*s-%s", (int)machine_len, machine_start, uid_str);

    pwd->pw_name = buffer;
    pwd->pw_uid = (uid_t)uid;
    pwd->pw_gid = (gid_t)uid;
    pwd->pw_gecos = "";
    pwd->pw_dir = "/nonexistent";
    pwd->pw_shell = "/bin/false";

    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}

