#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <pwd.h>

enum nss_status {
    NSS_STATUS_SUCCESS,
    NSS_STATUS_NOTFOUND,
    NSS_STATUS_UNAVAIL
};

enum nss_status get_user_account_info(const char* name, struct passwd* pwd, char* buffer, size_t buflen, int* errnop) {
    if (!name || !pwd || !buffer || buflen == 0 || !errnop) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    if (strncmp(name, "vu-", 3) != 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    const char* start = name + 3;
    const char* dash = strchr(start, '-');
    if (!dash) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    size_t machine_len = dash - start;
    if (machine_len == 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    char machine[256];
    strncpy(machine, start, machine_len);
    machine[machine_len] = '\0';

    const char* uid_str = dash + 1;
    char* endptr;
    uid_t uid = strtoul(uid_str, &endptr, 10);
    if (*endptr != '\0') {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    // Assume that perform_bus_call is a helper function defined elsewhere in the file
    // that performs the system bus call and returns user information.
    int success = perform_bus_call(machine, uid, buffer, buflen);
    if (!success) {
        *errnop = ENOENT;
        return NSS_STATUS_UNAVAIL;
    }

    pwd->pw_name = buffer;
    pwd->pw_uid = uid;
    pwd->pw_gid = uid; // Assuming same as user ID if not specified
    pwd->pw_dir = strdup("/home/virtual_user");
    pwd->pw_shell = strdup("/bin/bash");

    return NSS_STATUS_SUCCESS;
}
